contract_urls = []
contract_links = []
for county, data in TN_CONTRACT_COUNTIES.items():
    sections = [
        ('Tennessee contract-county framework','Tennessee identifies certain counties as contract counties that administer subsurface sewage disposal functions locally. SepticScope therefore uses the local county or health-department process for this guide rather than copying the ordinary TDEC field-office workflow used in non-contract counties.')
    ] + data['sections']
    sources = [
        ('TDEC — Septic System Construction Permit','https://www.tn.gov/environment/permits/water/septic-systems-permits/ssp/permit-water-septic-system-construction-permit.html')
    ] + data['sources']
    url = write_county_page('Tennessee','tennessee',county,data['authority'],data['contact'],sections,sources,verified='August 29, 2026')
    contract_urls.append(url)
    contract_links.append((county, data['authority']))

# Preserve the 86 TDEC-served counties and add only the locally validated contract counties.
tn_all_links = [(c, f'TDEC {o} Environmental Field Office') for c,o in tn_links] + contract_links
write_hub(
    'Tennessee','tennessee',sorted(tn_all_links),
    'Tennessee uses TDEC’s statewide Subsurface Sewage Disposal System program in most counties, while nine contract counties administer septic functions locally. SepticScope distinguishes those two paths instead of applying one workflow statewide.',
    'This hub now includes 92 verified Tennessee counties: the 86 TDEC-served counties plus six locally researched contract counties—Blount, Hamilton, Jefferson, Madison, Shelby, and Williamson. Davidson, Knox, and Sevier remain excluded until their current local procedures can be supported to the same standard.'
)

county_index = OUTPUT / 'counties' / 'index.html'
if county_index.exists():
    text = county_index.read_text(encoding='utf-8')
    text = text.replace('Browse 86 verified Tennessee county septic guides →','Browse 92 verified Tennessee county septic guides →')
    county_index.write_text(text, encoding='utf-8')

sitemap = OUTPUT / 'sitemap.xml'
if sitemap.exists():
    sm = sitemap.read_text(encoding='utf-8')
else:
    sm = '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>'
entries = ''.join(f'<url><loc>{u}</loc><lastmod>2026-08-29</lastmod></url>' for u in contract_urls if u not in sm)
if entries:
    sm = sm.replace('</urlset>', entries + '</urlset>')
    sitemap.write_text(sm, encoding='utf-8')

print(f'Tennessee contract-county expansion complete: +{len(contract_urls)} verified county guides')
